head.script:
scwin.add = function(x, y, width, height) {
    var widget = widgetContainer1.addWidgets({
        title: "widget" + scwin.wcount,
        titleClass: "w2widget_orange",
        src: "widgetContainer_WPF-1476_(WSQ-2446)_widget.xml",
        scope: true,
        x: x,
        y: y,
        unitWidth: width,
        unitHeight: height,
        params: "USER_DATA"
    });
    scwin.wcount++;
};
scwin.resize = function(widgetId, width, height) {
    var widget = widgetContainer1.resizeWidget(widgetId, width, height);
}
scwin.t1_onclick = function() {
    scwin.add(i++, 0, 1, 1);
};
scwin.onclickcustombtn = function() {
    console.log(arguments);
}
scwin.onwidgetmove = function() {
    console.log(arguments);
}
scwin.onwidgetresize = function() {
    console.log(arguments);
}
scwin.alert = function() {
    alert("scwin.alert() is called!!!!");
};
scwin.trigger1_onclick = function(e) {
    widgetContainer1.removeTitleClass("widget0", "w2widget_orange");
};
scwin.trigger2_onclick = function(e) {
    widgetContainer1.setTitleClass("widget0", "w2widget_orange");
};
scwin.checkVal1 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0_title')).getPropertyValue('background-color') == 'rgb(255, 165, 0)';
}
scwin.checkVal2 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'widgetContainer1_widget0_title')).getPropertyValue('background-color') != 'rgb(255, 165, 0)';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. TestData의 샘플(_main.xml)실행하고 'setTitleClass'버튼을 클릭한다.
    //1. Run the TestData sample (_main.xml) and click the 'setTitleClass' button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 'widget0' 위젯의 타이틀 색상이 오렌지색으로 보여진다.(style 적용)
    //1. The title color of the 'widget0' widget is shown in orange (apply style)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 다시 'removeTitleClass'버튼을 클릭한다.
    //2. Click the 'removeTitleClass' button again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 'widget0' 위젯의 타이틀 색상(오렌지)이 지워진다.(style 제거)
    //2. The title color of the 'widget0' widget (orange) is cleared (style removed)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    widgetContainer1.addWidgets({
        id: "widget0",
