        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        id: "widget1",
        title: "widget1",
        titleClass: "w2widget_blue",
        src: null,
        scope: true,
        x: 0,
        y: 1,
        unitWidth: 1,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        id: "widget2",
        title: "widget2",
        src: "widgetContainer_WPF-1476_(WSQ-2446)_widget.xml",
        scope: true,
        x: 0,
        y: 2,
        unitWidth: 1,
        unitHeight: 1
    });

    scwin.wcount = 0;
    window.i = 1;
    //widgetContainer1.setTitleClass("widget0","w2widget_orange");
    //widgetContainer1.removeTitleClass("widget0","w2widget_orange");
    /*
            scwin.add(0,0,2,2);
            scwin.add(4,0,3,3);
            //scwin.add(7,6,3,3);








             */
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
